import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"革","description":"高岛易断 - 革","frontmatter":{"title":"革","description":"高岛易断 - 革"},"headers":[],"relativePath":"zh/classics/takashima/049.md","filePath":"zh/classics/takashima/049.md"}'),i={name:"zh/classics/takashima/049.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="革" tabindex="-1">革 <a class="header-anchor" href="#革" aria-label="Permalink to “革”">​</a></h1><h2 id="革-1" tabindex="-1">革 <a class="header-anchor" href="#革-1" aria-label="Permalink to “革”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>革：己日乃孚。元亨利贞，悔亡。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《革》，改革也。日者《离》象，纳甲，《离》纳己，己为土，位居中。《易》道贵乎得中，过中则变，古人以已有变更之义。《仪礼》，“少牢馈食礼，日用丁己”，郑注，“必丁己者，取其自丁宁、自变己（更）”，（本书认为应读为己，为一家之见更），是已有革义也。五常以土为信，土即己也。将有改革，先示以信，“己日”者，为信孚于人之日也，故曰“己日乃孚”。《离》火生于《乾》二，《兑》金生于《乾》四，是卦从《乾》来，故“元亨利贞”四德皆具。有孚“悔亡”，己日之功也。王弼曰，“即日不孚，已日乃孚，已读作‘已事遄往’之已”，《疏》与《正义》，皆从其说。然《易》中用甲，用庚，用日，用月，各有精义，王说恐未然。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>泽中有火，革。君子以治历，明时。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>泽本有水之所，变而有火，是亦天地之变象也，故曰《革》。君子法之，“治历”者，推日月星辰之迁易，“明时”者，察分至寒暑之往来，故曰“君子以治历明时”。历者，天事也，时者，人事也，是顺天道而治人事也。昼夜为一日之革，晦望为十月之革，分至为一岁之革，即《彖》所云“天地革而四时成”之义也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：譬如有水之处，忽而出火，是气运之反常也，宜顺时改变，乃吉。</p><p>○　问战征：屯兵之地，防溪谷林木间着火，最宜谨慎。</p><p>○　问营商：《兑》为金，金入火则金熔矣，消耗之象。宜迁地贸易，乃可无咎。</p><p>○　问功名：龙门变化，烧尾之象，吉。</p><p>○　问婚姻：卦体上泽下火，泽有火，是水被火所制，夫为妻所制也。革者有出妻改娶之象。</p><p>○　问家宅：此宅防有火灾，急宜改迁。</p><p>○　问疾病：是肾水枯涸，肝火上炎之症，宜改延良医，顺时调养。</p><p>○　问讼事：此事本无中生有，灾自外来。宜改易讼词，揆度时日，其辩自明，其讼得直。</p><p>○　问六甲：生女。凡占此卦，皆女象，惟出月过时，变则成男。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>《离》为黄牛，《革》为牛皮，“巩”，扬子《方言》谓，“火干也”，是皮方去毛，以火干之，犹未成其《革》也。初居《离》之始，其象如之。革者本大有为之事，初爻卑下，其时其地，皆未当革，其才与德，亦不足以任革，恰如取黄牛之革，始用《离》火以干燥之而已，未可躁急而妄改也。《象传》以“不可以有为”释之，谓不可先时而革也。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：好运初来，犹宜固守，不可妄动。</p><p>○　问营商：商业初成，宜先立巩固之基，未可妄事更张也。</p><p>○　问功名：初出求名，其才未充，其时尚早，必待四五年后，方能变化腾达。</p><p>○　问婚姻：男女之年尚幼，未可拟亲，俟三年后，可以成就。</p><p>○　问家宅：此宅新造，屋宇坚固。</p><p>○　问疾病：病是胃火微弱，脾土过强，致中腹胀硬，有类黄疸之症。药宜消积健脾以治之。</p><p>○　问讼事：必是健讼，未易断结。</p><p>○　问六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>某友来，为摄绵土生意，愿出资金，与余合业，请卜一卦，以决盈亏。筮得《革》之《咸》。</p><p>断曰：卦体泽上火下，泽本为水土之合，火又能生土，《革》者，合水火以革土也，其象与制造摄绵土，适相符合。占得初爻，为生意在发靭之始，爻辞曰“巩用黄牛之革”。黄，中央之色，牛属土，“革”皮也，土之外面，亦称皮，“巩”，坚韧也。摄绵土者，取粘土，和石灰，入灶，用火煅炼，其中有水有土有火，合三者而《革》成之也。初爻事在始谋，犹未可遽用其革，第示其象之坚韧，如牛革然。就爻而推论之，阅一年而革可行，阅二年而革可成，四年人皆信用其革，五六年则革成之晶，愈精愈美。初时所云牛皮，后皆为虎豹，而有文采矣。爻辞详明切合，可信可喜。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二为内卦之主，居《离》之中，《彖》所云“己日乃孚”，二实当之。在《彖》曰“乃孚”，是天人先期其孚也；在爻日“乃革”，是时会适当可革也。既“孚”“乃革”，不言孚而孚在其中矣。二与五应，“征”者，往也，谓往应大人之命，以共启文明之运，故吉而“无咎”。《象传》以“行有嘉”释之，《离》为火，火主礼，凡国家变革之事，要不外制礼之大法，《周礼·大宗伯》所谓“嘉礼亲万民”者，此也，故曰“行有嘉”也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：行土运可以兴事立业，大佳。</p><p>○　问战征：宜择戊己日，行军接战，必可获胜。</p><p>○　问营商：于摄绵土生意最宜。凡新立买卖，必择土日开市大吉。</p><p>○　问功名：戊年或交土运必可成名。</p><p>○　问婚姻：可称嘉偶。</p><p>○　问家宅：修理旧宅，宜择土日。</p><p>○　问行人：戊己日可归。</p><p>○　问疾病：逢己日可愈，吉。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>缙绅某来，请占气运，筮得《革》之《夬》。</p><p>断曰：卦名曰《革》，去旧取新，重兴事业之象。卜得二爻，其地位在适当改革之时，知足下气运正盛，大可有为。“征吉”，征，往也。二应在五，五在外卦，谓当往外而从五，自能获吉。“己日”者，宜择戊己日起行，前往无咎。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三、四、五三爻，皆言“有孚”，是就《彖传》“乃孚”之辞，至再至三，而申明告示，以期其孚也。三处《离》之终，二既行《革》，则革之成败，正于三见之。操切行革，反以招败，故“征凶”；革当大事，革而不从，适以启祸，故“贞厉”。是骤革者危，不革亦危也。君子惟先求其孚而已，是以革之事未行，革之言先布，《离》为言，当《离》三爻，故为“三就”。昔盘庚迁殷，周公之告多方多士，皆反复详明，不嫌其言之烦，惟期其民之孚也。言既“三就”，则我之诚意，可深入于民心，民于此时，当必“有孚挛如”矣。或云“三就”者，如《左传》所云：“政不可不慎，务三而已，一择人，二因民，三从时。得此三者，而天人交孚矣。”其说亦通。《象传》以“又何之”释之，凡占象如《乾》之《坤》，“之”字皆作变解，谓“三就”而革，复有何变也。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：当此有事之秋，一不谨慎，则有凶危立至，宜再三筹度而行，方得众人信服。从此而往，时运大佳。</p><p>○　问战征：兵，凶事也，危事也，发军之日，先宜号令申明，斯信则人任，往无不利也。</p><p>○　问营商：未计其盈，宜先防其亏。贸易之道，以信为主，必得众商信从，乃可获利。</p><p>○　问功名：必三试可就。</p><p>○　问婚姻：得三人为媒，可成。</p><p>○　问家宅：宜三迁。</p><p>○　问讼事：始审再审至大审，三审乃直。</p><p>○　问疾病：症象本危，三日后可愈。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>某旧藩士，来请占藩政方向，筮得《革》之《随》。</p><p>断曰：此卦泽水在上，《离》火在下，火盛则灭水，水盛则灭火。《彖传》曰，“水火相息”，息或作灭，亦作生，灭而复生，是即去旧取新之义也，故谓之《革》。今占得三爻，三以阴居阳，处《离》之终，按数成于三，三爻为适当革事之成，一革以后，为凶为吉，亦在三爻，知藩政之成败，即在三爻时也。“革言”者，谓用革之议也；“三就”者，谓再三酌议而行之也。如是则人心信从，而革乃无咎，否则骤革固凶，不革亦危，是明示藩政之不可不革，而亦不可骤用其革也，足下其审慎！</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>革而议之谓之言，革而行之谓之命。四爻出《离》入《兑》，当改革之交，《彖》曰“革而当，其悔乃亡”，四得专之。《兑》二曰“孚兑，吉”，《象传》谓“孚兑之吉，信志也”，四爻曰“有孚吉”，而《象》亦曰“信志”，谓举大事，动大众，必先得民心，而后可大得志也。是《革》四爻，即《兑》二爻，故其辞同，其象亦同。“改命”者，必上膺天命，下顺人心，鼎革一新，如汤武之革命是也。后世托言汤武，而妄思改命者，类皆灭亡，盖革命必有汤武之志则吉，无汤武之志则凶，“改命”之吉，专指汤武而言。《象传》曰“信志”，亦谓此也。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：曰“悔亡”，曰“吉”，是灾悔既亡，而吉运来也。万事皆可改作，无不如志。</p><p>○　问营商：必是旧业重兴，大可得利。</p><p>○　问战征：改旗易辙，重振军令，可以开国，可以辟地，可以转败为胜，吉。</p><p>○　问功名：改武就文，可以成名。</p><p>○　问婚姻：不利原聘，利重婚。</p><p>○　问家宅：改作改造，大吉大利。</p><p>○　问讼事：灾悔已退，讼即可罢。</p><p>○　问失物：可寻得之。</p><p>○　问六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>友人某来，请占气运，筮得《革》之《既济》。</p><p>断曰：革者去故取新之卦，在人则衰运去而盛运来也。今占得四爻，知足下之气运方盛，从前灾悔已消，此后事业重新，进而谋事，成就无疑。但不利仍旧，惟利改作，故曰“改命”。“命”，命运也，人生命运，五年一换。《彖》取“己日”，以土为用，信亦为土，如丙子运后，换入丁丑，土运正旺，故吉。凡平素不利之事，一经改革，无往不利矣。后果然。</p><p>明治二十八年一月三十一日，我军陷威海卫，清国北洋舰队，据守刘公岛，抗拒我军。二月五日，筮得《革》之《既济》。</p><p>此卦我为内卦，属《离》火，清为外卦，属《兑》金，有以火铄金之象。卦名曰《革》，革者改也，四爻正当变革之时，以火器攻打铁舰，是全胜之占也。后果以水雷击沉艨舰，至十二日，北洋舰队悉败，炮台亦归我有。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五爻得《坤》气，《坤》为虎，《兑》属正西，白虎西方之宿，故五爻有虎象。“虎变”者，虎之毛羽，变而成文，愈变而愈美者也。五居尊位，故称“大人”，为《革》之主，风虎云龙，变化莫测，为《革》之至盛至当者也，“汤武革命”，即在此爻。“未占有孚”者，大人德位俱隆，躬任制作，将为天下更新，大启文明之化，而天下之被其化者，早巳输诚悦服，不敢或后，所谓不疑何卜？无容质诸于鬼神，故曰孚在占先也。孚于人，尤孚于天，是天与之，人归之，有见其孚而不见其革者矣。上互《乾》，《乾》为大人，非“乾道变化，各正性命”之大人，曷克臻此？《象传》以“文炳”释之，五处《兑》之中，兑为泽，为金，泽谓润泽而有文也，金亦有文象，下应《离》火，《离》为光，为明，其文更著。丙火为《离》，丙即炳，故炳字，从火从丙。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：如此大运，非“首出庶物”之大人，不克当此。若常人占得此爻，必能光前裕后，大振家声。</p><p>○　问战征：虎臣桓桓，威声早著，可不战而来降也。</p><p>○　问营商：白虎属西方之宿，西属秋，防货价至秋，大有变动。宜先订定价，自可获利，吉。</p><p>○　问功名：《乾》曰“云从龙，风从虎”，言各得其际会也，吉。</p><p>○　问婚姻：俗以白虎为不利，婚事未占先孚，犹言未嫁而先从也，为女不贞之象。</p><p>○　问家宅：虎动，亦不利。</p><p>○　问疾病：虎属寅，寅为木，是必肝木振动之症。不占先孚，必不药而愈也，吉。</p><p>○　问六甲：象本生女，一变则为男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>有某诸侯，使其庶子嗣末家，末家者幕府旗下之士也。戊辰之变，旗下之徒数百人，推末家为队长，将谋举事，其家臣五十余人，多与其谋。于是本家忧之，遣使促归，且曰若不归藩，恐朝廷有疑于本藩，祸将不测。于是议论纷起，判成两党，一在促归，一在不归，迄将一月，议终不决。一日使人招余，余应招而往，两党数百之士，充满藩邸，各述其意，余皆闻之，曰：今日所谋之事，实国家之大事也，国家之大事，关夫天数，非可以私心判决者也。不如问诸《易》占，众咸以为是，乃筮得《革》之《丰》。</p><p>断曰：此卦可谓适切今日之事者也。今日诸君之所论，一欲尽忠于幕府，一欲奉朝命而为国，非即《彖》所云“二女同居，其志不相得”者乎？在仆观之，卦名曰《革》，是明示以用革之象。爻为君位，辞曰“大人虎变”，“大人”者，谓应天承运之大人。虎为百兽之长，“变”，即革也，明示其人为当革之人，其时为革之时。时既当革，安得不应天顺人，以应其革乎？诸君之论，半皆泥于仍旧，不知卦象，专在去旧取新，故知仍旧者非，故有虑革之而民弗信，不知二爻三爻，皆曰“有孚”，当未革而先期其孚，至五则革道已成矣，故曰“未占有孚”。且经此一革，不特大受信用，且将率天下之民，日进于文明之化，行见重熙累洽，光被四表，即可见于此日了。宜速去此地，以归本藩，是仆所得天数之占断也。两党之士，闻之皆愕然，无敢出一辞，于是主君大嘉余之占断，即日整装而归。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上爻居卦之极，有德无位，必是去位之贤大夫也，故称“君子”。豹饰，大夫之服，故曰“豹变”。盖革之成，始于四，整于五，终于上，是以五之圣君，既得显虎文之灿，而上之大夫，亦得增“豹变”之华。“小人”，细民也，“面”者，向也，“革面”者，向化也，言小人皆潜移默化，于光天之下，革面洗心，欣欣然而有喜色也，是之谓“小人革面”。“征凶”者，上与三应，上之“征凶”，亦即三之“征凶”也。谓大变既定，若复纷更自取多事，必如汤之昭德建中，惟期裕后，武之修文偃武，不复用兵，是即所谓居贞则吉也。《象传》以“文蔚”释之，“蔚”，深密之貌；豹隐处雾雨，欲泽其身，以成其文，犹言君子相与于文明之治，以增服饰之光也。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：运当全盛，光华显著，惟宜守成，无事纷更。</p><p>○　问营商：创业以来，有名有利，已臻美备，此后宜知足谨守。</p><p>○　问功名：上居卦之终，功名早极，劝令功成身退，所谓“人死留名，豹死留皮”也。</p><p>○　问战征：军用多取兽名，兕甲虎贲，皆用之以焕其文而扬其威也。上六爻已终，谓战已定，宜罢兵退守，不可前往。</p><p>○　问婚姻：上与三应，九三阳也，上六阴也，三日“三就，有孚”，当再三逑合，自可成就，吉。</p><p>○　问家宅：爻位在上，其宅基必高。曰“征凶”，知迁移不利；曰“居贞吉”，知居之得安也。</p><p>○　问失物：物已变革，寻亦不得。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>缙绅某来，请占气运，筮得《革》之《同人》。</p><p>断曰：此卦一变旧弊，改进文明之卦也。今占得上爻，曰“君子豹变”，“君子”者，谓有德无位者也，豹亦为隐居之兽，正合贵下退位闲居之象也。想曩时赞襄维新之治，以成“虎变”之文，贵下固与有功焉。豹较虎而小，虎属五爻为君，知豹变即指贵下。贵下之功绩既著，文明亦显，正可相与守成，无事多求，故曰“征凶，居贞吉”。贵下之气运如是，正可安亨纳福。</p>',109)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
